import { type GetProducts, type GetOrders, type GetAlerts, type GetPurchaseOrders } from "wasp/server/operations";

export const getProducts: GetProducts<void, any> = async (_args, context) => {
  if (!context.user) {
    throw new Error("Not authorized");
  }
  return context.entities.Product.findMany({
    include: {
      supplier: true,
    },
  });
};

export const getOrders: GetOrders<void, any> = async (_args, context) => {
  if (!context.user) {
    throw new Error("Not authorized");
  }
  return context.entities.Order.findMany({
    include: {
      orderItems: {
        include: {
          product: true,
        },
      },
    },
  });
};

export const getAlerts: GetAlerts<void, any> = async (_args, context) => {
  if (!context.user) {
    throw new Error("Not authorized");
  }
  return context.entities.Alert.findMany({
    orderBy: {
      createdAt: "desc",
    },
  });
};

export const getPurchaseOrders: GetPurchaseOrders<void, any> = async (_args, context) => {
  if (!context.user) {
    throw new Error("Not authorized");
  }
  return context.entities.PurchaseOrder.findMany({
    include: {
      supplier: true,
      product: true,
    },
  });
};

import { app, page, route, query, action } from "@wasp.sh/spec";
import { MainPage } from "./src/MainPage" with { type: "ref" };
import { LoginPage } from "./src/LoginPage" with { type: "ref" };
import { SignupPage } from "./src/SignupPage" with { type: "ref" };
import { getProducts } from "./src/queries" with { type: "ref" };
import { getOrders } from "./src/queries" with { type: "ref" };
import { getAlerts } from "./src/queries" with { type: "ref" };
import { getPurchaseOrders } from "./src/queries" with { type: "ref" };
import { fulfillOrder } from "./src/actions" with { type: "ref" };
import { seedData } from "./src/seeds" with { type: "ref" };

export default app({
  name: "warehouse-tracker",
  title: "Warehouse Inventory & Fulfillment Tracker",
  wasp: { version: "^0.24.0" },
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  db: {
    seeds: [seedData],
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),
    query(getProducts, { entities: ["Product", "Supplier"] }),
    query(getOrders, { entities: ["Order", "OrderItem", "Product"] }),
    query(getAlerts, { entities: ["Alert"] }),
    query(getPurchaseOrders, { entities: ["PurchaseOrder", "Supplier", "Product"] }),
    action(fulfillOrder, { entities: ["Order", "OrderItem", "Product", "Alert", "PurchaseOrder"] }),
  ],
});

